import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static class FastScanner {
        StreamTokenizer tokenizer;

        FastScanner(InputStream stream) {
            tokenizer = new StreamTokenizer(new BufferedReader(new InputStreamReader(stream)));
            tokenizer.ordinaryChars(33, 126);
            tokenizer.wordChars(33, 126);
        }

        int nextInt() throws IOException {
            tokenizer.nextToken();
            return Integer.parseInt(tokenizer.sval);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[][] dp = new long[n + 1][n + 1];

        for (int j = 0; j <= n; j++) {
            for (int i = 0; i <= j; i++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 1;
                } else {
                    long value = 0;
                    if (j != i) value += dp[i][j - 1];
                    if (i != 0) value += dp[i - 1][j];
                    dp[i][j] = value % MOD;
                }
            }
        }

        long ans = 0;
        for (int j = n; j >= 0; j--) {
            for (int i = j - 1; i >= 0; i -= 2) {
                ans += dp[i][j];
                ans %= MOD;
            }
        }

        System.out.println(ans);
    }
}
